2067	static int
2068	demux_stream_send_to_dst(Scheduler *sch, const SchedulerNode dst,
2069	                         uint8_t *dst_finished, AVPacket *pkt, unsigned flags)
2070	{
2071	    int ret;
2072	
2073	    if (*dst_finished)
