  81	ThreadQueue *tq_alloc(unsigned int nb_streams, size_t queue_size,
  82	                      enum ThreadQueueType type)
  83	{
  84	    ThreadQueue *tq;
  85	    int ret;
  86	
  87	    tq = av_mallocz(sizeof(*tq));
