  97	    ret = pthread_mutex_init(&tq->lock, NULL);
  98	    if (ret) {
  99	        pthread_cond_destroy(&tq->cond_read);
 100	        av_freep(&tq);
 101	        return NULL;
 102	    }
 103	
 104	    tq->cond_write = av_calloc(nb_streams, sizeof(*tq->cond_write));
 105	    if (!tq->cond_write)
 106	        goto fail;
 107	    for (tq->nb_cond_write = 0; tq->nb_cond_write < nb_streams; tq->nb_cond_write++) {
 108	        ret = pthread_cond_init(&tq->cond_write[tq->nb_cond_write], NULL);
