 148	int tq_send(ThreadQueue *tq, unsigned int stream_idx, void *data)
 149	{
 150	    int *finished;
 151	    int ret;
 152	
 153	    av_assert0(stream_idx < tq->nb_streams);
 154	    finished = &tq->finished[stream_idx];
 155	
 156	    pthread_mutex_lock(&tq->lock);
 157	
 158	    if (*finished & FINISHED_SEND) {
 159	        ret = AVERROR(EINVAL);
 160	        goto finish;
 161	    }
 162	
 163	    while (!(*finished & FINISHED_RECV) && !can_write(tq, stream_idx))
 164	        pthread_cond_wait(&tq->cond_write[stream_idx], &tq->lock);
 165	
 166	    if (*finished & FINISHED_RECV) {
 167	        ret = AVERROR_EOF;
 168	        *finished |= FINISHED_SEND;
 169	    } else {
 170	        ret = av_fifo_write(tq->fifo_stream_index, &stream_idx, 1);
 171	        if (ret < 0)
 172	            goto finish;
 173	
 174	        ret = av_container_fifo_write(tq->fifo, data, 0);
 175	        if (ret < 0)
 176	            goto finish;
 177	
 178	        tq->stream_count[stream_idx]++;
 179	        pthread_cond_broadcast(&tq->cond_read); // signal downstream
 180	    }
 181	
 182	finish:
 183	    pthread_mutex_unlock(&tq->lock);
 184	
 185	    return ret;
 186	}
