 234	int tq_receive(ThreadQueue *tq, int *stream_idx, void *data, int flags)
 235	{
 236	    int ret;
 237	
 238	    *stream_idx = -1;
 239	
 240	    pthread_mutex_lock(&tq->lock);
 241	
 242	    while (1) {
 243	        ret = receive_locked(tq, stream_idx, data);
 244	
 245	        if (ret == AVERROR(EAGAIN) && !(flags & THREAD_QUEUE_FLAG_NO_BLOCK)) {
 246	            pthread_cond_wait(&tq->cond_read, &tq->lock);
 247	            continue;
 248	        }
 249	
 250	        break;
 251	    }
 252	
 253	    pthread_mutex_unlock(&tq->lock);
 254	
 255	    return ret;
 256	}
