 274	void tq_receive_finish(ThreadQueue *tq, unsigned int stream_idx)
 275	{
 276	    av_assert0(stream_idx < tq->nb_streams);
 277	
 278	    pthread_mutex_lock(&tq->lock);
 279	
 280	    /* mark the stream as recv-finished;
 281	     * next time the producer thread tries to send for this stream, it will
 282	     * get an EOF and send-finished flag will be set */
 283	    tq->finished[stream_idx] |= FINISHED_RECV;
 284	    pthread_cond_broadcast(&tq->cond_write[stream_idx]);
 285	
 286	    pthread_mutex_unlock(&tq->lock);
 287	}
