3452	    if (ret < 0)
3453	        goto finish;
3454	
3455	    fg_thread_set_name(fg);
3456	
3457	    // if we have all input parameters the graph can now be configured
3458	    if (ifilter_has_all_input_formats(fg)) {
3459	        ret = configure_filtergraph(fg, &fgt);
3460	        if (ret < 0) {
