3512	        } else {
3513	            av_assert1(o == FRAME_OPAQUE_EOF);
3514	            ret = send_eof(&fgt, ifilter, fgt.frame->pts, fgt.frame->time_base);
3515	        }
3516	        av_frame_unref(fgt.frame);
3517	        if (ret == AVERROR_EOF) {
