 206	{
 207	    MuxStream *ms = ms_from_ost(ost);
 208	    AVFormatContext *s = mux->fc;
 209	    int64_t fs;
 210	    uint64_t frame_num;
 211	    int ret;
 212	
 213	    fs = filesize(s->pb);
 214	    atomic_store(&mux->last_filesize, fs);
 215	    if (fs >= mux->limit_filesize) {
 216	        ret = AVERROR_EOF;
 217	        goto fail;
 218	    }
 219	
 220	    ret = mux_fixup_ts(mux, ms, pkt);
 221	    if (ret < 0)
 222	        goto fail;
 223	
 224	    ms->data_size_mux += pkt->size;
